PROGRAM ST_S03_KASSATION
VAR
    steg     : INT := 0;
    tmrPsh   : TON;
    trigPec  : R_TRIG;
    trigWgt  : R_TRIG;
    wgtOk    : BOOL := FALSE;
    wgtError : BOOL := FALSE;
END_VAR

tmrPsh(IN := (steg = 2), PT := T#400ms);
trigPec(CLK := ST210_REJ_PEC);
trigWgt(CLK := ST210_WGT_STABLE);

wgtOk := (ST210_WGT_VAL >= 16.0) AND (ST210_WGT_VAL <= 20.0);
wgtError := (ST210_WGT_VAL < 5.0) OR (ST210_WGT_VAL > 50.0);

IF NOT EMG_OK OR (ST210_WGT_STABLE AND wgtError) THEN
    ST210_CNV_RUN := FALSE;
    ST210_PSH_OUT := FALSE;
    steg := 0;
ELSE
    ST210_CNV_RUN := TRUE;

    IF trigWgt.Q THEN
        ST210_IN_CNT := ST210_IN_CNT + 1;
        IF wgtOk THEN
            ST210_OK_CNT := ST210_OK_CNT + 1;
            steg := 0;
        ELSE
            ST210_PSH_OUT := TRUE;
            steg := 2;
        END_IF;
    END_IF;

    IF steg = 2 THEN
        IF trigPec.Q THEN
            ST210_REJ_CNT := ST210_REJ_CNT + 1;
        END_IF;
        IF tmrPsh.Q THEN
            ST210_PSH_OUT := FALSE;
            steg := 0;
        END_IF;
    END_IF;
END_IF;
END_PROGRAM

